        crossorigin="anonymous"
        async>
</script>

<script>
  function setGiscusTheme() {
    const iframe = document.querySelector('iframe.giscus-frame');
    if (!iframe) return;
    const theme = document.documentElement.getAttribute('data-theme') === 'dark'
      ? '{{ .Site.Params.comments.giscus.darktheme }}'
      : '{{ .Site.Params.comments.giscus.lighttheme }}';
    iframe.contentWindow.postMessage(
      { giscus: { setConfig: { theme } } },
      'https://giscus.app'
    );
  }
  document.addEventListener('DOMContentLoaded', () => {
    const observer = new MutationObserver(setGiscusTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    setGiscusTheme();
  });
</script>
{{- end -}}

/* ---------------------------------------------------------------------------
 * Site-level overrides for PaperMod
 * Kept intentionally small: brand color, CJK font stack, headline rhythm,
 * and a slightly narrower reading width for CJK content.
 * --------------------------------------------------------------------------- */

/* --- Brand color (Cranberry red) --------------------------------------------
 * Light mode:  #db5079  (cranberry pink)
 * Dark mode:   #ef7fa4  (lighter, AA-readable on PaperMod dark background)
 * ------------------------------------------------------------------------- */
:root {
  --primary: #db5079;
  --main-width: 760px;
}

:root[data-theme="dark"] {
  --primary: #ef7fa4;
}

/* --- CJK font stack --------------------------------------------------------
 * Applies to body and inline code so Chinese/Japanese/Korean text renders
 * with native system fallbacks (PingFang SC on macOS, Microsoft YaHei on
 * Windows, Source Han Sans SC where installed, etc.).
 * ------------------------------------------------------------------------- */
body {
  font-family:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei',
    'Source Han Sans SC', sans-serif;
}

code,
pre,
kbd,
samp {
  font-family:
    'Sarasa Mono SC', 'JetBrains Mono', Menlo, Consolas,
    'PingFang SC', 'Microsoft YaHei', monospace;
}

/* --- Headline rhythm --------------------------------------------------------
 * PaperMod default line-height is ~1.2; CJK titles look cramped at that
 * density, so loosen h1–h3 to 1.4. Body paragraph spacing is nudged slightly
 * for consistent vertical rhythm between CJK and Latin text.
 * ------------------------------------------------------------------------- */
h1,
h2,
h3 {
  line-height: 1.4;
}

.post-content p,
.first-entry .entry-content p {
  margin-bottom: 1.1em;
}

/* --- Daily Spark card ------------------------------------------------------
 * Sits below home-info on the homepage. Renders site.Data.daily_spark
 * (written by .github/workflows/daily-spark.yml). Uses theme tokens so it
 * tracks light/dark mode automatically.
 * ------------------------------------------------------------------------- */
.daily-spark {
  margin-top: 1.6em;
  padding: 1em 1.2em;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.daily-spark__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1em;
  margin-bottom: 0.6em;
  color: var(--secondary);
  font-size: 0.85em;
  letter-spacing: 0.02em;
}
.daily-spark__label { font-weight: 600; }
.daily-spark__date { font-variant-numeric: tabular-nums; }
.daily-spark__body { display: flex; flex-wrap: wrap; align-items: center; gap: 0.6em 0.8em; }
.daily-spark__tag {
  display: inline-block;
  padding: 0.12em 0.7em;
  border: 1px solid var(--primary);
  border-radius: 999px;
  color: var(--primary);
  font-size: 0.78em;
  font-weight: 600;
  line-height: 1.6;
}
.daily-spark__title {
  margin: 0;
  font-size: 1.05em;
  font-weight: 700;
  line-height: 1.4;
}
.daily-spark__task {
  margin: 0;
  flex-basis: 100%;
  color: var(--secondary);
  font-size: 0.95em;
  line-height: 1.55;
}

